 #ifndef _LIBCPP_FLOAT_H
 #define _LIBCPP_FLOAT_H

@@ -97,3 +103,5 @@ Macros:
 #endif   // defined(__cplusplus) && __cplusplus < 201103L && defined(_LIBCPP_USE_FROZEN_CXX03_HEADERS)

